INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 19, 'theory', 'Quiz: operator overloading');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 19, 0, 'What does the expression a + b turn into?', '["type(a).__add__(a, b)", "a.add(b)", "__plus__(b, a)", "b.__add__(a)"]', 0, 'The addition method of the left operand is called first; the right operand''s reflected method is tried only if the left one returned NotImplemented.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 19, 1, 'What happens on 3 * v if Vector has __mul__ but no __rmul__?', '["A vector multiplied by 3 is returned", "int calls Vector.__mul__", "Python swaps the operands itself and it works", "TypeError: int cannot be multiplied by Vector"]', 3, 'int.__mul__ returns NotImplemented, and Vector has no reflected method, so the operation is not supported.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 19, 2, 'What must the __iadd__ method return?', '["None", "self", "A new object of the same type", "A number"]', 1, 'The result of __iadd__ is stored back into the variable: without return self, None ends up there.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 19, 3, 'Why does the built-in sum() need __radd__ on your class?', '["sum() swaps the addends", "sum() calls __iadd__", "It starts from 0: first it computes 0 + first_item", "Without it sum() returns 0"]', 2, 'sum(items) is 0 + item1 + item2..., so the class must be able to stand on the right of a number.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 19, 4, 'How does __index__ differ from __int__?', '["It doesn''t, they are synonyms", "__index__ must be an exact integer and is used for indexes, slices, hex() and range()", "__index__ works only with strings", "__int__ is needed for slices"]', 1, '__int__ may lose data (int(3.9)), while __index__ says the object is an integer by nature, which is why float has no __index__.');
